TEST_CASE(variadic_promotions)
{
    const char *text = "extern fn printf(fmt: *u8, ..) -> i32\n"
                       "fn f(p: *u8, b: f32) -> i32 {\n"
                       "    return printf(p, 1, -1, 3000000000, 18446744073709551615, 2.5, b)\n"
                       "}\n";
    Arena arena = { 0 };
    Lexer lx;
    Checker c;
    ParsedFile *files = check_texts(&c, &arena, &lx, &text, 1, 1);

    const IrCode *code = &c.ir.code;
    const IrFunc *f = &c.ir.funcs[0];
    u32 call = f->first;
    while (code->kinds[call] != IR_CALL_C) {
        call++;
    }
    const u32 *args = code->extra + f->first_extra + code->bs[call];

    u32 want[] = { TYPE_ID_I32, TYPE_ID_I32, TYPE_ID_I64, TYPE_ID_U64, TYPE_ID_F64, TYPE_ID_F64 };
    bool ok = c.ndiags == 0 && c.ir.nfuncs == 1 && args[0] == 7;
    for (u32 i = 0; ok && i < 6; i++) {
        u32 x = args[2 + i];
        u32 type = x & IR_CONST ? code->consts[f->first_const + (x & ~IR_CONST)].type
                                : code->types[f->first + x];
        ok = type == want[i];
    }

    check_free(&c);
    free(files);
    arena_free(&arena);
    REQUIRE(ok);
    return true;
}

TEST_CASE(callback_list)
{
    const char *text = "extern fn each(f: extern fn(x: int) -> int) -> int\n"
                       "extern fn twice(x: int) -> int\n"
                       "fn tap(x: int) -> int {\n"
                       "    return x\n"
                       "}\n"
                       "fn g() -> int {\n"
                       "    return each(tap) + each(twice) + each(tap) + each(twice)\n"
                       "}\n";
    Arena arena = { 0 };
    Lexer lx;
    Checker c;
    ParsedFile *files = check_texts(&c, &arena, &lx, &text, 1, 1);

    const IrCode *code = &c.ir.code;
    const IrFunc *f = &c.ir.funcs[1];
    u32 got[4];
    u32 n = 0;
    for (u32 i = f->first; i < f->first + f->count; i++) {
        if (code->kinds[i] == IR_CALLBACK && n < 4) {
            got[n++] = code->as[i];
        }
    }
    bool ok = c.ndiags == 0 && c.ir.nfuncs == 2 && c.ir.ncallbacks == 2 && n == 4 &&
              c.ir.callbacks[0] == 3 && c.ir.callbacks[1] == 2 && got[0] == 0 &&
              got[1] == 1 && got[2] == 0 && got[3] == 1;

    check_free(&c);
    free(files);
    arena_free(&arena);
    REQUIRE(ok);
    return true;
}

TEST_CASE(export_list)
{
    const char *text = "extern fn each(f: extern fn(x: int) -> int) -> int\n"
                       "export fn a(x: int) -> int {\n"
                       "    return x\n"
                       "}\n"
                       "fn b(x: int) -> int {\n"
                       "    return x\n"
                       "}\n"
                       "export fn c(x: int) -> int {\n"
                       "    return x\n"
                       "}\n"
                       "fn g() -> int {\n"
                       "    return each(b) + each(a) + each(c) + a(1)\n"
                       "}\n";
    Arena arena = { 0 };
    Lexer lx;
    Checker c;
    ParsedFile *files = check_texts(&c, &arena, &lx, &text, 1, 1);

    const IrCode *code = &c.ir.code;
    const IrFunc *f = &c.ir.funcs[3];
    u32 got[3];
    u32 n = 0;
    for (u32 i = f->first; i < f->first + f->count; i++) {
        if (code->kinds[i] == IR_CALLBACK && n < 3) {
            got[n++] = code->as[i];
        }
    }
    bool ok = c.ndiags == 0 && c.ir.nfuncs == 4 && c.ir.ncallbacks == 3 && c.ir.nexports == 2 &&
              c.ir.callbacks[0] == 2 && c.ir.callbacks[1] == 4 && c.ir.callbacks[2] == 3 &&
              n == 3 && got[0] == 2 && got[1] == 0 && got[2] == 1;

    check_free(&c);
    free(files);
    arena_free(&arena);
    REQUIRE(ok);
    return true;
}

TEST_CASE(files)
{
    const char *texts[] = {
        "const A := B * 2\nstruct S { t: T }\nconst Dup := 1\n",
        "const B := 21\nstruct T { s: S }\nconst Dup := 2\n",
    };
    REQUIRE(checks_to(
        texts,
        2,
        2,
        "a:2:8: `S` depends on itself through `T`\n"
        "b:3:7: `Dup` is already declared at a:3:7\n"
        "const A = 42\nstruct S { t: T }\nconst Dup = 1\nconst B = 21\nstruct "
        "T { s: S }\nconst Dup = 2\n"
    ));
    return true;
}

