TEST_CASE(extern_globals)
{
    const char *texts[] = {
        "extern count: i32\n"
        "extern fn abs(x: i32) -> i32\n",
        "extern origin: Point\n"
        "pub extern table: [4]?*Point\n"
        "fn bump() -> i32 {\n"
        "    count += 1\n"
        "    origin.y = origin.x\n"
        "    p := &count\n"
        "    table[1] = &origin\n"
        "    return p.* + abs(count)\n"
        "}\n"
        "struct Point { x: int, y: int }\n",
    };
    REQUIRE(checks_to(
        texts,
        2,
        0,
        "extern count: i32\n"
        "extern fn abs(x: i32) -> i32\n"
        "extern origin: Point\n"
        "pub extern table: [4]?*Point\n"
        "fn bump() -> i32\n"
        "struct Point { x: int, y: int }\n"
    ));
    REQUIRE(compiles_to(
        texts,
        2,
        0,
        true,
        "fn bump() -> i32\n"
        "    slots: $0: *i32, p: *i32\n"
        "    %0 = c-global *i32 count\n"
        "    store *i32 $0, %0\n"
        "    %2 = load *i32 $0\n"
        "    %3 = load-at i32 %2\n"
        "    %4 = add i32 %3, 1\n"
        "    %5 = load *i32 $0\n"
        "    store-at i32 %5, %4\n"
        "    %7 = c-global *Point origin\n"
        "    %8 = field *int %7, .y\n"
        "    %9 = c-global *Point origin\n"
        "    %10 = field *int %9, .x\n"
        "    %11 = load-at int %10\n"
        "    store-at int %8, %11\n"
        "    %13 = c-global *i32 count\n"
        "    store *i32 p, %13\n"
        "    %15 = c-global *[4]?*Point table\n"
        "    %16 = index *?*Point %15, 1\n"
        "    %17 = c-global *Point origin\n"
        "    store-at ?*Point %16, %17\n"
        "    %19 = load *i32 p\n"
        "    %20 = load-at i32 %19\n"
        "    %21 = c-global *i32 count\n"
        "    %22 = load-at i32 %21\n"
        "    %23 = call-c i32 abs(%22)\n"
        "    %24 = add i32 %20, %23\n"
        "    ret i32 %24\n"
    ));
    return true;
}

