TEST_CASE(depth_limit)
{
    u32 n = 1100;
    size_t cap = (size_t)n * 32;
    char *text = malloc(cap);
    size_t len = 0;
    for (u32 i = 0; i < n; i++) {
        len += (size_t)snprintf(text + len, cap - len, "const C%u := C%u + 1\n", i, i + 1);
    }
    snprintf(text + len, cap - len, "const C%u := 0\n", n);

    const char *texts[] = { text };
    char *got = check_files(texts, 1, 1, false);
    free(text);

    const char
        *want = "a:1000:15: this needs more than 1000 nested declarations\n";
    bool ok = strncmp(got, want, strlen(want)) == 0 &&
              strstr(got, "const C1099 = 1\n") != NULL;
    if (!ok) {
        fprintf(stderr, "depth limit\n  got: %.200s\n", got);
    }
    free(got);
    REQUIRE(ok);
    return true;
}

static bool
checks_doubling_structs(const char *leaf, const char *want)
{
    u32 n = 64;
    size_t cap = (size_t)n * 40 + 64;
    char *text = malloc(cap);
    size_t len = 0;
    for (u32 i = 0; i < n; i++) {
        u32 next = i + 1;
        len += (size_t)snprintf(text + len, cap - len, "struct L%u { a: L%u, b: L%u }\n", i, next, next);
    }
    snprintf(text + len, cap - len, "struct L%u { %s }\nextern fn f(x: L0) -> int\n", n, leaf);

    const char *texts[] = { text };
    char *got = check_files(texts, 1, 1, false);
    free(text);

    bool ok = strncmp(got, want, strlen(want)) == 0;
    if (!ok) {
        fprintf(stderr, "doubling structs\n  got: %.200s\n", got);
    }
    free(got);
    return ok;
}

TEST_CASE(doubling_structs)
{
    const char *refused = "a:66:13: the checker doesn't support this yet\n";
    REQUIRE(checks_doubling_structs("x: int", "struct L0 "));
    REQUIRE(checks_doubling_structs("v: u8x16", refused));
    return true;
}

typedef struct
{
    Arena arena;
    Lexer lx;
    Checker c;
    ParsedFile *files;
    IrReference ref;
} Program;

static bool
load_program(Program *p, const char *text)
{
    *p = (Program){ 0 };
    p->files = check_texts(&p->c, &p->arena, &p->lx, &text, 1, 1);
    check_print_diagnostics(stderr, &p->c);
    if (p->c.ndiags) {
        return false;
    }
    ir_reference_init(&p->ref, &p->c);
    return true;
}

static u32
decl_named(Program *p, const char *name)
{
    u32 before = p->lx.names.count;
    u32 id = names_intern(&p->lx.names, name, (u32)strlen(name));
    u32 decl = id <= before ? p->c.package_names[id] : 0;
    assert(decl);
    return decl;
}

static void
release_program(Program *p)
{
    ir_reference_free(&p->ref);
    check_free(&p->c);
    free(p->files);
    arena_free(&p->arena);
}

static bool
runs_to(const char *text, const VectorRun *runs, size_t n)
{
    Program p;
    bool ok = load_program(&p, text);
    for (size_t i = 0; ok && i < n; i++) {
        const VectorRun *r = &runs[i];
        u64 args[3] = { (u64)r->args[0], (u64)r->args[1], (u64)r->args[2] };
        u64 got = 0;
        int trap = ir_reference_run(&p.ref, decl_named(&p, r->name), args, &got);
        if (trap != r->trap || (!trap && (int64_t)got != r->want)) {
            fprintf(
                stderr,
                "vectors: %s(%lld, %lld, %lld) gave %lld (trap %d), want %lld (trap %d)\n",
                r->name,
                (long long)r->args[0],
                (long long)r->args[1],
                (long long)r->args[2],
                (long long)got,
                trap,
                (long long)r->want,
                r->trap
            );
            ok = false;
        }
    }
    release_program(&p);
    return ok;
}

static bool
grid_agrees(Program *p, const GridFunction *g)
{
    u32 decl = decl_named(p, g->name);
    for (int64_t a = 0; a < 16; a++) {
        for (int64_t b = 0; b < 16; b++) {
            for (int64_t op = 0; op < 20; op++) {
                int64_t k = (a * 3 + b + op) & (g->lanes - 1);
                u64 args[4] = { (u64)a, (u64)b, (u64)op, (u64)k };
                u64 got = 0;
                int trap = ir_reference_run(&p->ref, decl, args, &got);
                u64 want = g->oracle(a, b, op, k);
                if (trap || got != want) {
                    fprintf(
                        stderr,
                        "vectors: %s(%lld, %lld, %lld, %lld) gave %llu (trap %d), want %llu\n",
                        g->name,
                        (long long)a,
                        (long long)b,
                        (long long)op,
                        (long long)k,
                        (unsigned long long)got,
                        trap,
                        (unsigned long long)want
                    );
                    return false;
                }
            }
        }
    }
    return true;
}

TEST_CASE(vectors)
{
    REQUIRE(runs_to(VECTOR_BODY, VECTOR_BODY_RESULTS, NVECTOR_BODY_RESULTS));
    REQUIRE(runs_to(VECTOR_RUNS, VECTOR_RESULTS, NVECTOR_RESULTS));

    Program p;
    bool ok = load_program(&p, VECTOR_GRID);
    for (size_t f = 0; ok && f < NVECTOR_GRID_FUNCTIONS; f++) {
        ok = grid_agrees(&p, &VECTOR_GRID_FUNCTIONS[f]);
    }
    release_program(&p);
    REQUIRE(ok);
    return true;
}

static u32
token_line(const ParsedFile *f, u32 token)
{
    u32 line = 1;
    for (u32 p = 0; p < f->tokens.starts[token]; p++) {
        line += f->src[p] == '\n';
    }
    return line;
}

static bool
has_positions(const Checker *c, const ParsedFile *f, const IrFunc *fn, u32 steps)
{
    const IrLine *lines = c->ir.code.lines + fn->first_line;
    u32 head = token_line(f, f->nodes.tokens[c->decls.roots[fn->decl]]);
    u32 body = f->nodes.tokens[c->decls.bodies[fn->decl]];
    bool arrow = f->tokens.kinds[body] == TK_FAT_ARROW;
    u32 want = arrow ? steps + 3 : 1;
    bool ok = fn->nlines == want && lines[want - 1].end == fn->count;
    for (u32 k = 0; ok && k < want; k++) {
        u32 line = token_line(f, lines[k].token);
        ok = (k == 0 || lines[k].end > lines[k - 1].end) &&
             line == (want > 1 && k == want - 1 ? head : head + 1 + k);
    }
    if (!ok) {
        fprintf(
            stderr,
            "check test: the function at line %u has %u positions, want %u\n",
            head,
            fn->nlines,
            want
        );
    }
    return ok;
}

TEST_CASE(positions)
{
    enum
    {
        STEPS = 70,
    };
    static const char *const names[] = { "first", "second", "third" };
    size_t cap = 3 * (STEPS + 4) * 16 + 128;
    char *text = malloc(cap);
    size_t len = (size_t)snprintf(text, cap, "fn outer() -> int {\n    return first() + second()\n}\n");
    for (u32 k = 0; k < 3; k++) {
        if (k == 2) {
            len += (size_t)snprintf(text + len, cap - len, "fn again() -> int {\n    return third()\n}\n");
        }
        len += (size_t)snprintf(text + len, cap - len, "fn %s() => blk: {\n    x := 0\n", names[k]);
        for (u32 i = 0; i < STEPS; i++) {
            len += (size_t)snprintf(text + len, cap - len, "    x += %u\n", k + 1);
        }
        len += (size_t)snprintf(text + len, cap - len, "    break blk x\n}\n");
    }

    Arena arena = { 0 };
    Lexer lx;
    Checker c;
    const char *texts[] = { text };
    ParsedFile *files = check_texts(&c, &arena, &lx, texts, 1, 1);
    bool ok = c.ndiags == 0 && c.ir.nfuncs == 5;
    u32 total = 0;
    for (u32 f = 0; ok && f < c.ir.nfuncs; f++) {
        ok = has_positions(&c, files, &c.ir.funcs[f], STEPS);
        total += c.ir.funcs[f].nlines;
    }
    ok = ok && total == c.ir.code.nlines;

    check_free(&c);
    free(files);
    arena_free(&arena);
    free(text);
    REQUIRE(ok);
    return true;
}

TEST_CASE(statement_positions)
{
    static const char text[] =
        "fn walk(n: int) -> int {\n"
        "    x := 0\n"
        "    y: int\n"
        "    while x < n {\n"
        "        x += 1\n"
        "    }\n"
        "    for k in 0..n {\n"
        "        y += k\n"
        "    }\n"
        "    if x > 3 {\n"
        "        x = 1\n"
        "    } else {\n"
        "        x = 2\n"
        "    }\n"
        "    return x + y\n"
        "}\n";
    static const u32 want[] = { 2, 3, 4, 5, 4, 7, 8, 7, 10, 11, 13, 15 };

    Arena arena = { 0 };
    Lexer lx;
    Checker c;
    const char *texts[] = { text };
    ParsedFile *files = check_texts(&c, &arena, &lx, texts, 1, 1);
    bool ok = c.ndiags == 0 && c.ir.nfuncs == 1;
    u32 got[16];
    u32 n = 0;
    for (u32 k = 0; ok && k < c.ir.funcs[0].nlines && n < 16; k++) {
        u32 token = c.ir.code.lines[c.ir.funcs[0].first_line + k].token;
        got[n++] = token_line(files, token);
    }
    ok = ok && n == sizeof want / sizeof want[0] &&
         memcmp(got, want, sizeof want) == 0;
    if (!ok) {
        fprintf(stderr, "check test: statement positions:");
        for (u32 k = 0; k < n; k++) {
            fprintf(stderr, " %u", got[k]);
        }
        fputc('\n', stderr);
    }

    check_free(&c);
    free(files);
    arena_free(&arena);
    REQUIRE(ok);
    return true;
}

